const { body, param, query, validationResult } = require('express-validator');

// Body parsing with size limits (also prevents large payload DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Example of how future routes should use validation
app.post('/users',
  requireAuth,
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to proceed
  }
);
```

---

## Finding 5 — `/health` Leaks Server Timing Information
**Severity: 🟡 Low**
**OWASP: A05:2021 – Security Misconfiguration**

The `/health` endpoint returns `new Date().toISOString()`, which reveals the server's internal clock. This aids timing attacks and TOTP/token exploitation if an attacker can use the server's time as a reference.

```js
// ❌ Current
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Recommendation:** Remove the timestamp, or if uptime monitoring requires it, gate the route behind auth or network-level access controls (e.g., only accessible from your internal monitoring CIDR).

```js
// ✅ Recommended
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // No timing data exposed
});
```

---

## Finding 6 — No CORS Policy
**Severity: 🟠 Medium**
**OWASP: A05:2021 – Security Misconfiguration**

With no CORS configuration, Express's default behavior allows all cross-origin requests. If this API is ever consumed by a browser-based frontend, any malicious website can make credentialed requests to it.

**Recommendation:** Explicitly configure CORS with an allowlist:

```js
// ✅ Recommended
const cors = require('cors');

const allowedOrigins = [
  'https://yourapp.com',
  'https://admin.yourapp.com',
  // Add staging/dev origins as needed
];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS policy violation: origin ${origin} not allowed`));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

## Finding 7 — No Centralized Error Handling
**Severity: 🟡 Low**
**OWASP: A09:2021 – Security Logging and Monitoring Failures**

There is no error handler middleware. Unhandled errors in Express will propagate default stack traces to the client, leaking internal file paths, dependency versions, and application structure.

**Recommendation:** Add a centralized error handler as the *last* middleware:

```js
// ✅ Recommended
// Development: log full error; Production: return safe generic message
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // Always log internally
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Never expose internals to the client
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An internal server error occurred',
  });
});
```

---

## Finding 8 — No Security Logging or Audit Trail
**Severity: 🟠 Medium**
**OWASP: A09:2021 – Security Logging and Monitoring Failures**

There is no request logging. You cannot detect attacks, debug incidents, or audit access without logs.

**Recommendation:** Add structured logging with `morgan` or `pino`:

```js
// ✅ Recommended
const morgan = require('morgan');

// Log all requests with method, URL, status, response time, and IP
app.use(morgan(':method :url :status :response-time ms - :remote-addr'));

// For production, use structured JSON logging (pino is excellent):
// const pino = require('pino-http');
// app.use(pino());
```

---

