// const users = await db.query(`SELECT * FROM users WHERE id = ${req.query.id}`);

// Always use parameterized queries:
const users = await db.query('SELECT id, name, email FROM users WHERE id = $1', [req.query.id]);

// Or use a query builder with built-in parameterization:
const users = await knex('users').select('id', 'name', 'email').where({ id: req.query.id });
```

