```js
'use strict';

require('dotenv').config(); // load env vars before anything else

const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const morgan  = require('morgan');
const rateLimit = require('express-rate-limit');
const { param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// ── Security middleware ───────────────────────────────────────────────────────
app.use(helmet());
app.use(express.json({ limit: '10kb' }));

// CORS
const corsOptions = {
  origin: (origin, cb) => {
    const allowlist = (process.env.ALLOWED_ORIGINS || '').split(',');
    (!origin || allowlist.includes(origin)) ? cb(null, true) : cb(new Error('CORS violation'));
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
};
app.use(cors(corsOptions));

// Rate limiting
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100, standardHeaders: true }));

// Logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ── Auth middleware ───────────────────────────────────────────────────────────
function requireAuth(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(403).json({ error: 'Forbidden' });
  }
}

// ── Routes ────────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => res.status(200).json({ status: 'ok' }));

app.get('/users', requireAuth, async (req, res, next) => {
  try {
    const users = await getUsersFromDB(); // from a proper service layer
    res.json(users);
  } catch (err) {
    next(err);
  }
});

// ── Centralized error handler (must be last) ──────────────────────────────────
app.use((err, req, res, next) => {
  console.error(err.stack);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error',
  });
});

// ── Server ────────────────────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;
const HOST = process.env.HOST || '127.0.0.1';
app.listen(PORT, HOST, () =>
  console.log(`Server on ${HOST}:${PORT} [${process.env.NODE_ENV ?? 'development'}]`)
);

module.exports = app;
```

