  const result = UserQuerySchema.safeParse(req.query);
  if (!result.success) {
    return res.status(400).json({ error: 'Invalid query parameters', details: result.error.flatten() });
  }
  // Replace with real DB query using parameterized queries / ORM
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users.map(sanitizeUser));
});

// ── Global error handler (must be last) ───────────────────────────────────────
app.use((err, req, res, _next) => {
  const status = err.status || err.statusCode || 500;
  req.log?.error({ err, status }, 'unhandled error');
  res.status(status).json({
    error: status < 500 ? err.message : 'An unexpected error occurred',
  });
});

app.listen(3000, () => logger.info('Server running on port 3000'));
module.exports = app;
