### 🔴 Finding 2 — No Authentication or Authorization Anywhere (OWASP A07)

**File:** `app.js` — entire file

**Problem:** The application has **no authentication layer whatsoever**. Both `/health` and `/users` are fully public. There is no concept of sessions, tokens, or identity.

**Fix:** Implement JWT-based authentication middleware (or use an established library like `passport`):

```js
// ✅ middleware/auth.js
const jwt = require('jsonwebtoken');

// Secret loaded from environment — never hardcoded
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  throw new Error('FATAL: JWT_SECRET environment variable is not set.');
}

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }, (err, user) => {
    if (err) {
      // Distinguish expired vs. invalid without leaking details to caller
      const message = err.name === 'TokenExpiredError'
        ? 'Token expired.'
        : 'Invalid token.';
      return res.status(403).json({ error: message });
    }
    req.user = user;
    next();
  });
}

module.exports = authenticateToken;
```

