### 🟠 Finding 6 — No Input Validation Framework (OWASP A03)

**File:** `app.js` — entire file

**Problem:** The app performs **zero input validation** on query parameters, route params, or request bodies. Any future endpoint that touches a database or external service would be immediately vulnerable to injection attacks (SQLi, NoSQLi, command injection).

**Fix:** Add `zod` (or `joi`) validation at the route level, enforced before any business logic:

```js
// ✅ FIXED — validation middleware using zod
const { z } = require('zod');

function validate(schema) {
  return (req, res, next) => {
    const result = schema.safeParse({
      body: req.body,
      query: req.query,
      params: req.params,
    });
    if (!result.success) {
      return res.status(400).json({
        error: 'Invalid request.',
        details: result.error.flatten(), // structured, safe error details
      });
    }
    // Replace req fields with the validated+coerced values
    req.body = result.data.body ?? req.body;
    req.query = result.data.query ?? req.query;
    req.params = result.data.params ?? req.params;
    next();
  };
}

// Example: validate a future /users/:id route
const getUserSchema = z.object({
  params: z.object({
    id: z.string().regex(/^\d+$/, 'ID must be numeric'),
  }),
});

app.get('/users/:id', authenticateToken, validate(getUserSchema), (req, res) => {
  const userId = parseInt(req.params.id, 10); // safe — already validated
  // ...
});
```

