**Recommendation:** Install and wire up a validation library before adding any input-bearing routes:

```js
const { z } = require('zod'); // or use joi, express-validator, etc.

// Define schema for the route parameter
const UserByIdSchema = z.object({
  id: z.coerce.number().int().positive(),
});

app.get('/users/:id', requireAuth, (req, res) => {
  const result = UserByIdSchema.safeParse(req.params);
  if (!result.success) {
    return res.status(400).json({ error: 'Invalid user ID', details: result.error.flatten() });
  }

  const { id } = result.data; // guaranteed to be a safe positive integer
  const user = db.query('SELECT id, name FROM users WHERE id = $1', [id]); // parameterized
  res.json(user);
});
```

